/// <summary>
/// This class handles the dialog for updating the order extract screen route, routestop, confirmshipdate
/// </summary>
class METOrderExtractScreenModifyDialog
{
    protected Dialog        dialog;
    protected DialogField   dlgShippingDateConfirmed, dlgRoute, dlgRouteStop, dlgUpdateStatus;

    private SalesShippingDateConfirmed  shippingDateConfirmed;
    private METRoute                    metRoute;
    private METRouteStopNum             metRouteStop;
    private NoYesId                     updateStatus;

    boolean                             updateSalesTable;
    
}

Method.Source:
    /// <summary>
    /// Runs the logic
    /// </summary>
    /// <param name = "_args">arguments</param>
    public static void main(Args _args)
    {
        Dialog                              dialog;
        SalesTable                          slTbl;
        METOrderExtractScreenModifyDialog   dialogOrderExtractScreen;
        FormRun                             formRun         = _args.caller();
        FormDataSource                      salesTable_ds   = formRun.dataSource(formDataSourceStr(METOrderExtractScreen, SalesTable));
        Map                                 map             = formRun.getmap();
        

        dialogOrderExtractScreen    = new METOrderExtractScreenModifyDialog();
        
        dialog = dialogOrderExtractScreen.dialog(slTbl);

        //The code will only be executed if the user click on Yes
        if (dialog.run())
        {
            dialogOrderExtractScreen.getFromDialog();
            if (dialogOrderExtractScreen.validate())
            {
                dialogOrderExtractScreen.updateOrderExtractScreenMap(map);
                
                salesTable_ds.executeQuery();
            }
            
        }
    }

    /// <summary>
    /// Updates <c>SalesTable</c> with parameters.
    /// </summary>
    /// <param name = "_map">Map buffer</param>
    private void updateOrderExtractScreenMap(Map _map)
    {
        #OCCRetryCount
        SalesTable      salesTable;

        try
        {
            ttsbegin;
            MapEnumerator mapEnumerator = _map.getEnumerator();
            while (mapEnumerator.moveNext())
            {
                int64       recId = mapEnumerator.currentKey();
                SalesId     value = mapEnumerator.currentValue();
                    
                update_recordset salesTable
                        setting METRoute                = metRoute,
                                METRouteStopNum         = metRouteStop,
                                ShippingDateConfirmed   = shippingDateConfirmed
                        where salesTable.RecId == recId;

                METSalesOrderShipmentLoadHeader::createShippmentLoadFromSalesTable(value, false, false);
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            error("@MET:METBulkUpdateError");
        }

        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
                
       
    }

    /// <summary>
    /// Updates <c>SalesTable</c> with parameters.
    /// </summary>
    /// <param name = "_salesTable">Salestable buffer</param>
    private void updateOrderExtractScreenRec(SalesTable _salesTable)
    {
        #OCCRetryCount

        SalesLine       salesLine;
        METSalesLine    metSalesLine;

        boolean         updateShipDate;
        try
        {
            ttsbegin;
            _salesTable.selectForUpdate(true);

            if (!updateStatus)
            {
                updateSalesTable = true;
                if (_salesTable.METRoute != metRoute)
                {
                    _salesTable.METRoute = metRoute;
                }

                if (_salesTable.METRouteStopNum != metRouteStop)
                {
                    _salesTable.METRouteStopNum = metRouteStop;
                }

                if (_salesTable.ShippingDateConfirmed != shippingDateConfirmed)
                {
                    _salesTable.ShippingDateConfirmed = shippingDateConfirmed;
                    updateShipDate = true;
                }
            }
            else if (updateStatus && _salesTable.METOrderExtractStatus == METOrderExtractStatus::ReadyForExtract)
            {
                _salesTable.METOrderExtractStatus =  METOrderExtractStatus::Open;
                updateSalesTable = true;
            }
            else if(updateStatus && _salesTable.METOrderExtractStatus == METOrderExtractStatus::Open)
            {
                updateSalesTable = false;

                if (!_salesTable.METRoute || !_salesTable.METRouteStopNum)
                {
                    updateSalesTable = checkFailed(strFmt("@MET:SOExtractRouteWarning", _salesTable.SalesId));
                }
                else
                {
                    //Check if atleast one salesline has reserved quantity;
                    while select salesLine
                            where salesLine.SalesId == _salesTable.SalesId
                            && salesLine.SalesStatus != SalesStatus::Canceled
                            && salesLine.SalesStatus != SalesStatus::Invoiced
                            && !salesLine.SourcingCompanyId
                            join metSalesLine where metSalesLine.SalesLine == salesLine.RecId
                            && metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted
                    {
                        if (salesLine.reservedPhysical())
                        {
                            updateSalesTable = true;
                            break;
                        }
                    }
                    if (!updateSalesTable)
                    {
                        //If the SO has just Intercompany lines then update status to 'Ready for extract'
                        select firstonly RecId from salesLine
                            where salesLine.SalesId == _salesTable.SalesId
                            && salesLine.SalesStatus != SalesStatus::Canceled
                            && salesLine.SourcingCompanyId
                            join metSalesLine where metSalesLine.SalesLine == salesLine.RecId
                            && metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted;
                        if (salesline.RecId)
                        {
                            updateSalesTable = true;
                        }

                    }
                }

                if (updateSalesTable)
                {
                    _salesTable.METOrderExtractStatus =  METOrderExtractStatus::ReadyForExtract;
                }
            }

            if (updateSalesTable)
            {
                _salesTable.update();
                info(StrFmt("@MET:METBulkUpdateInfo", _salesTable.SalesId));
            }
            
            if (updateShipDate)
            {
                update_recordset salesLine
                setting ShippingDateConfirmed = _salesTable.ShippingDateConfirmed
                    where salesLine.SalesId == _salesTable.SalesId
                    && salesLine.ShippingDateConfirmed != ShippingDateConfirmed;
            }
                
            ttscommit;
        }
        catch (Exception::Error)
        {
            error("@MET:METBulkUpdateError");
        }

        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
                
       
    }

    /// <summary>
    /// Validate dialog parameters.
    /// </summary>
    /// <returns>true if validated successfully; otherwise false</returns>
    protected boolean validate()
    {
   
        boolean     ret             = true;  
        //CS - CB173_SalesOrderExtract - PS
        int         lenRoute        = strLen(metRoute);
        int         lenRouteStop    = strLen(int2Str(metRouteStop));
        int         posRoute        = lenRoute;
        str         lastFourDigit   = subStr(metRoute, posRoute, -4);
        //CE - CB173_SalesOrderExtract - PS

        if (!updateStatus && (!metRoute || !metRouteStop))
        {
            ret = checkFailed("@SYS37918");
        }

        //CS - CB173_SalesOrderExtract - PS
        if (lenRoute < 4)
        {
            ret = checkFailed("@MET:InvalidFormat4DigitRoute");
        }
        else
        {
            if (!Global::isInteger(lastFourDigit))
            {
                ret = checkFailed("@MET:InvalidFormat4DigitRoute");
            }
        }

        if (lenRouteStop > 2)
        {
            ret = checkFailed("@MET:InvalidFormatRouteStop99");
        }
        
        if (metRouteStop < 0 || metRouteStop > 99)
        {
            ret = checkFailed("@MET:InvalidFormatRouteStop99");
        }

        if (!metRoute || !metRouteStop || !shippingDateConfirmed)
        {
            ret = false;
        }
        //CE - CB173_SalesOrderExtract - PS

        return ret;
    }

    /// <summary>
    /// Builds the dialog.
    /// </summary>
    /// <param name = "_salesTable">table record used to set initial values</param>
    /// <returns>The dialog</returns>
   protected Dialog dialog(SalesTable _salesTable)
    {
        //Create a Dialog with title
        dialog = new Dialog("@MET:METBulkUpdate");
        dlgRoute        = dialog.addField(extendedTypeStr(METRoute), "@SYS4190");
        dlgRoute.value(strFmt("@MET:METStrfmt1",_salesTable.METRoute));
        dlgRoute.mandatory_RU(true);

        dlgRouteStop   = dialog.addField(extendedTypeStr(METRouteStopNum), "@MET:METRouteStop");
        dlgRouteStop.value(strFmt("@MET:METStrfmt1",_salesTable.METRouteStopNum));
        dlgRouteStop.mandatory_RU(true);
        
        dlgShippingDateConfirmed  = dialog.addField(extendedTypeStr(SalesShippingDateConfirmed), "@MET:METConfirmedShippingDate");
        dlgShippingDateConfirmed.value(_salesTable.ShippingDateConfirmed);

        dlgUpdateStatus = dialog.addField(extendedTypeStr(NoYesId), "@SYS32754");
        dlgUpdateStatus.visible(false);
         
        //Create a "Label" do Dialog
        dialog.addText("@MET:METProceed");

        dialog.formBuildDesign().dialogSize(0);

        return dialog;
    }

    /// <summary>
    /// Retrieves values from the dialog after it is completed.
    /// </summary>
    /// <returns>true if values are retrieved successfully; otherwise, false.</returns>
    protected boolean getFromDialog()
    {
        boolean ret = true;

        shippingDateConfirmed   = dlgShippingDateConfirmed.value();
        metRoute                = dlgRoute.value();
        metRouteStop            = dlgRouteStop.value();
        updateStatus            = dlgUpdateStatus.value();
        
        return ret;
    }

/// <summary>
/// Instantiates <c>METOrderExtractScreenModifyDialog</c> class
/// </summary>
/// <returns>Instance of <c>METOrderExtractScreenModifyDialog</c> class</returns>
public static METOrderExtractScreenModifyDialog construct()
{
    return new METOrderExtractScreenModifyDialog();
}
